pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }

    if let Some(heartbeat) = decode_v2_heartbeat(bytes) {
        return Ok(Msg::Heartbeat(heartbeat));
    }

    if let Some(hello) = decode_v2_hello(bytes) {
        return Ok(Msg::Hello(hello));
    }

    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!(r#"{{"v":2,"hello":"{}"}}"#, escape_json_string(name)),
        Msg::Heartbeat(sequence) => format!(r#"{{"v":2,"heartbeat":{}}}"#, sequence),
    }
}

fn escape_json_string(value: &str) -> String {
    let mut escaped = String::new();
    for ch in value.chars() {
        match ch {
            '"' => escaped.push_str(r#"\""#),
            '\\' => escaped.push_str(r#"\\"#),
            '\n' => escaped.push_str(r#"\n"#),
            '\r' => escaped.push_str(r#"\r"#),
            '\t' => escaped.push_str(r#"\t"#),
            ch if ch.is_control() => escaped.push_str(&format!(r#"\u{:04x}"#, ch as u32)),
            ch => escaped.push(ch),
        }
    }
    escaped
}

fn decode_v2_heartbeat(bytes: &str) -> Option<u32> {
    let prefix = r#"{"v":2,"heartbeat":"#;
    let encoded = bytes.strip_prefix(prefix)?.strip_suffix('}')?;
    encoded.parse().ok()
}

fn decode_v2_hello(bytes: &str) -> Option<String> {
    let prefix = r#"{"v":2,"hello":"#;
    let encoded = bytes.strip_prefix(prefix)?.strip_suffix('"')?;
    let mut decoded = String::new();
    let mut chars = encoded.chars();

    while let Some(ch) = chars.next() {
        if ch != '\\' {
            decoded.push(ch);
            continue;
        }

        match chars.next()? {
            '"' => decoded.push('"'),
            '\\' => decoded.push('\\'),
            '/' => decoded.push('/'),
            'b' => decoded.push('\u{0008}'),
            'f' => decoded.push('\u{000c}'),
            'n' => decoded.push('\n'),
            'r' => decoded.push('\r'),
            't' => decoded.push('\t'),
            'u' => {
                let code = chars.by_ref().take(4).collect::<String>();
                if code.len() != 4 || !code.chars().all(|digit| digit.is_ascii_hexdigit()) {
                    return None;
                }
                decoded.push(char::from_u32(u32::from_str_radix(&code, 16).ok()?)?);
            }
            _ => return None,
        }
    }

    Some(decoded)
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::{decode, Msg};

    #[test]
    fn decodes_ping_frame_successfully() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn roundtrips_heartbeat_sequence() {
        let encoded = super::encode(&Msg::Heartbeat(42));
        assert_eq!(encoded, r#"{"v":2,"heartbeat":42}"#);
        assert!(matches!(decode(&encoded), Ok(Msg::Heartbeat(42))));
    }
}
